INSERT INTO `certificats` VALUES (1,'REMUS-2026-001','Alexandre Mbarga','alexandre.mbarga@example.com','Créer un site web moderne avec l\'IA','Cette formation a couvert les notions essentielles et les compétences pratiques pour concevoir, développer et déployer un site web professionnel à l\'aide des outils d\'IA.','Cohorte Alpha · Octobre 2026','Mention Très Bien (Félicitations du Jury)','30 heures','15 Juin 2026 – 15 Juillet 2026','Débutant → Intermédiaire','À Douala, Cameroun','Dr Remus','2026-10-15','Ingénierie de Prompt & IA Générative\nDéveloppement Web Frontend (HTML5, CSS3, JavaScript moderne)\nArchitecture Backend & Base de données MySQL\nDéploiement en Production & Sécurisation SSL','valide',NULL,'2026-09-26 09:59:34'),(2,'CERT-2026-0158','Jean Kévin Mbarga','jean.kevin@example.com','Créer un site web avec l’IA','Cette formation a couvert les notions essentielles et les compétences pratiques pour concevoir, développer et déployer un site web professionnel à l\'aide des outils d\'IA.','Cohorte Juin 2026','Mention Très Bien','30 heures','15 Juin 2026 – 15 Juillet 2026','Débutant → Intermédiaire','À Douala, Cameroun','Dr Remus','2026-07-15','Next.js 14, Tailwind CSS, Claude 3.5 Sonnet, Vercel CI/CD, API REST','valide',NULL,'2026-09-26 10:28:56');
