INSERT INTO `formations` VALUES (1,'web-ia-octobre-2026','Créer un site web avec l\'IA','PROCHAINE COHORTE','De l\'idée à la mise en ligne, construis ton propre site web avec l\'aide des outils d\'intelligence artificielle.','15 octobre 2026','4 semaines',10,7,'ouvert',1,'2026-09-24 21:34:41','2026-09-24 22:24:36'),(2,'dev-ia','Développer avec l\'IA','DÉVELOPPEMENT','Passer du site statique à une application web dynamique en utilisant l\'IA comme copilote de code.','Date à venir','5 semaines',10,10,'prochainement',0,'2026-09-24 21:34:41','2026-09-24 21:34:41'),(3,'premier-projet-web','Premier projet web','INITIATION','De zéro absolu à un premier projet web complet et hébergé. Aucun prérequis technique exigé.','Date à venir','3 semaines',12,12,'prochainement',0,'2026-09-24 21:34:41','2026-09-24 21:34:41'),(4,'freelance-ia','Lancer son freelance','BUSINESS','Structurer son offre, trouver ses premiers clients et gérer son activité freelance avec l\'appui de l\'IA.','Date à venir','4 semaines',10,10,'prochainement',0,'2026-09-24 21:34:41','2026-09-24 21:34:41'),(5,'archive-cohorte-03','Créer un site web avec l\'IA (Cohorte #03)','COHORTE #03','10 participants ont conçu, intégré et mis en ligne leur plateforme web avec hébergement cloud.','Juin 2026','4 semaines',10,0,'termine',0,'2026-09-24 21:34:41','2026-09-24 21:34:41'),(6,'archive-cohorte-02','Automatisation & Workflows IA (Cohorte #02)','COHORTE #02','8 participants ont automatisé des processus métiers complets : gestion de formulaires et intégration API.','Février 2026','4 semaines',8,0,'termine',0,'2026-09-24 21:34:41','2026-09-24 21:34:41'),(7,'archive-cohorte-01','Fondations du Web Moderne & IA (Cohorte #01)','COHORTE #01','8 participants ont appris les fondamentaux du code propre assisté par l\'IA.','Novembre 2025','4 semaines',8,0,'termine',0,'2026-09-24 21:34:41','2026-09-24 21:34:41');
