INSERT INTO `projects` VALUES (1,1,'SCADA & IoT','Plateforme Web SCADA Temps Réel','Application web de supervision industrielle avec monitoring en direct de 4 lignes de production, WebSockets, alertes automatiques et gestion des consignes machines.','#','#','[\"React\", \"Node.js\", \"MQTT\", \"InfluxDB\", \"Docker\"]','<svg viewBox=\"0 0 800 220\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" class=\"cs-preview-svg\">\n            <!-- Barre de titre simulée -->\n            <rect x=\"20\" y=\"16\" width=\"760\" height=\"32\" rx=\"6\" fill=\"rgba(255,255,255,0.08)\"/>\n            <circle cx=\"40\" cy=\"32\" r=\"7\" fill=\"rgba(255,255,255,0.25)\"/>\n            <circle cx=\"62\" cy=\"32\" r=\"7\" fill=\"rgba(255,255,255,0.15)\"/>\n            <circle cx=\"84\" cy=\"32\" r=\"7\" fill=\"rgba(255,255,255,0.1)\"/>\n            <rect x=\"110\" y=\"24\" width=\"120\" height=\"16\" rx=\"4\" fill=\"rgba(255,255,255,0.15)\"/>\n            <!-- 4 widgets KPI -->\n            <rect x=\"20\" y=\"64\" width=\"170\" height=\"70\" rx=\"8\" fill=\"rgba(255,255,255,0.06)\" stroke=\"rgba(255,255,255,0.18)\" stroke-width=\"1\"/>\n            <rect x=\"210\" y=\"64\" width=\"170\" height=\"70\" rx=\"8\" fill=\"rgba(255,255,255,0.06)\" stroke=\"rgba(255,255,255,0.18)\" stroke-width=\"1\"/>\n            <rect x=\"400\" y=\"64\" width=\"170\" height=\"70\" rx=\"8\" fill=\"rgba(255,255,255,0.06)\" stroke=\"rgba(255,255,255,0.18)\" stroke-width=\"1\"/>\n            <rect x=\"590\" y=\"64\" width=\"190\" height=\"70\" rx=\"8\" fill=\"rgba(255,255,255,0.06)\" stroke=\"rgba(255,255,255,0.18)\" stroke-width=\"1\"/>\n            <!-- Textes KPI -->\n            <rect x=\"36\" y=\"80\" width=\"60\" height=\"10\" rx=\"3\" fill=\"rgba(255,255,255,0.3)\"/>\n            <rect x=\"36\" y=\"100\" width=\"80\" height=\"18\" rx=\"4\" fill=\"rgba(255,255,255,0.45)\"/>\n            <rect x=\"226\" y=\"80\" width=\"60\" height=\"10\" rx=\"3\" fill=\"rgba(255,255,255,0.25)\"/>\n            <rect x=\"226\" y=\"100\" width=\"70\" height=\"18\" rx=\"4\" fill=\"rgba(255,255,255,0.35)\"/>\n            <!-- Courbe de signal temps réel -->\n            <rect x=\"20\" y=\"148\" width=\"760\" height=\"56\" rx=\"8\" fill=\"rgba(255,255,255,0.04)\" stroke=\"rgba(255,255,255,0.12)\" stroke-width=\"1\"/>\n            <polyline points=\"36,188 90,162 145,178 200,155 255,170 310,148 365,165 420,152 475,168 530,155 585,172 640,158 695,175 750,160 764,168\" stroke=\"rgba(255,255,255,0.75)\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n            <circle cx=\"310\" cy=\"148\" r=\"4\" fill=\"rgba(255,255,255,0.9)\" stroke=\"none\"/>\n          </svg>',NULL,1,'2026-09-24 21:49:57','2026-09-24 21:55:27'),(2,2,'Passerelle Edge','Passerelle Modbus → Cloud & Web UI','Module embarqué sur Raspberry Pi collectant des registres de capteurs industriels, avec interface de configuration web locale et synchronisation cloud chiffrée.','#','#','[\"Python\", \"FastAPI\", \"Docker\", \"SQLite\", \"Raspberry Pi\"]','<svg viewBox=\"0 0 800 220\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" class=\"cs-preview-svg\">\n            <!-- Schéma de flux Modbus → Edge → Cloud en palette du site -->\n            <!-- PLC/Capteur -->\n            <rect x=\"30\" y=\"70\" width=\"140\" height=\"80\" rx=\"10\" fill=\"rgba(255,255,255,0.06)\" stroke=\"rgba(255,255,255,0.25)\" stroke-width=\"1.5\"/>\n            <rect x=\"50\" y=\"88\" width=\"40\" height=\"30\" rx=\"4\" fill=\"rgba(255,255,255,0.15)\"/>\n            <rect x=\"100\" y=\"92\" width=\"50\" height=\"8\" rx=\"3\" fill=\"rgba(255,255,255,0.25)\"/>\n            <rect x=\"100\" y=\"106\" width=\"40\" height=\"8\" rx=\"3\" fill=\"rgba(255,255,255,0.18)\"/>\n            <text x=\"100\" y=\"138\" font-size=\"10\" fill=\"rgba(226,232,240,0.85)\" font-family=\"monospace\">PLC / Capteurs</text>\n            <!-- Flèche Modbus -->\n            <path d=\"M172 110 L240 110\" stroke=\"rgba(255,255,255,0.5)\" stroke-width=\"2\" stroke-dasharray=\"6,3\"/>\n            <polygon points=\"240,106 252,110 240,114\" fill=\"rgba(255,255,255,0.5)\"/>\n            <text x=\"190\" y=\"103\" font-size=\"9\" fill=\"rgba(96,165,250,0.85)\" font-family=\"monospace\">Modbus TCP</text>\n            <!-- Edge (Raspberry Pi) -->\n            <rect x=\"254\" y=\"60\" width=\"160\" height=\"100\" rx=\"10\" fill=\"rgba(255,255,255,0.08)\" stroke=\"rgba(255,255,255,0.3)\" stroke-width=\"1.5\"/>\n            <circle cx=\"334\" cy=\"84\" r=\"18\" fill=\"rgba(255,255,255,0.15)\" stroke=\"rgba(255,255,255,0.35)\" stroke-width=\"1\"/>\n            <rect x=\"286\" y=\"108\" width=\"96\" height=\"8\" rx=\"3\" fill=\"rgba(255,255,255,0.3)\"/>\n            <rect x=\"300\" y=\"122\" width=\"68\" height=\"8\" rx=\"3\" fill=\"rgba(255,255,255,0.2)\"/>\n            <text x=\"298\" y=\"148\" font-size=\"10\" fill=\"rgba(226,232,240,0.85)\" font-family=\"monospace\">Edge Gateway</text>\n            <!-- Flèche Cloud -->\n            <path d=\"M416 110 L484 110\" stroke=\"rgba(255,255,255,0.5)\" stroke-width=\"2\" stroke-dasharray=\"6,3\"/>\n            <polygon points=\"484,106 496,110 484,114\" fill=\"rgba(255,255,255,0.5)\"/>\n            <text x=\"426\" y=\"103\" font-size=\"9\" fill=\"rgba(96,165,250,0.85)\" font-family=\"monospace\">HTTPS/TLS</text>\n            <!-- Cloud -->\n            <ellipse cx=\"580\" cy=\"100\" rx=\"80\" ry=\"45\" fill=\"rgba(255,255,255,0.08)\" stroke=\"rgba(255,255,255,0.25)\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/>\n            <rect x=\"540\" y=\"88\" width=\"80\" height=\"24\" rx=\"6\" fill=\"rgba(255,255,255,0.18)\"/>\n            <text x=\"556\" y=\"104\" font-size=\"10\" fill=\"rgba(226,232,240,0.85)\" font-family=\"monospace\">FastAPI + DB</text>\n            <!-- Web UI -->\n            <path d=\"M660 100 L700 100\" stroke=\"rgba(255,255,255,0.5)\" stroke-width=\"2\"/>\n            <polygon points=\"700,96 712,100 700,104\" fill=\"rgba(255,255,255,0.5)\"/>\n            <rect x=\"714\" y=\"72\" width=\"62\" height=\"56\" rx=\"6\" fill=\"rgba(255,255,255,0.08)\" stroke=\"rgba(255,255,255,0.25)\" stroke-width=\"1\"/>\n            <rect x=\"722\" y=\"82\" width=\"46\" height=\"8\" rx=\"3\" fill=\"rgba(255,255,255,0.25)\"/>\n            <rect x=\"722\" y=\"96\" width=\"36\" height=\"8\" rx=\"3\" fill=\"rgba(255,255,255,0.18)\"/>\n            <rect x=\"722\" y=\"110\" width=\"40\" height=\"8\" rx=\"3\" fill=\"rgba(255,255,255,0.3)\"/>\n            <text x=\"720\" y=\"140\" font-size=\"9\" fill=\"rgba(226,232,240,0.8)\" font-family=\"monospace\">Web UI</text>\n          </svg>',NULL,1,'2026-09-24 21:49:57','2026-09-24 21:55:27'),(3,3,'Maintenance 4.0','Dashboard de Maintenance Prédictive','Visualisation des vibrations et températures de moteurs industriels. Calcul automatique des seuils d\'usure et génération de rapports prévisionnels.','#','#','[\"Grafana\", \"Vue.js\", \"PostgreSQL\", \"Python\"]','<svg viewBox=\"0 0 800 220\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" class=\"cs-preview-svg\">\n            <!-- Header du dashboard -->\n            <rect x=\"20\" y=\"16\" width=\"760\" height=\"28\" rx=\"5\" fill=\"rgba(255,255,255,0.08)\"/>\n            <rect x=\"36\" y=\"24\" width=\"100\" height=\"12\" rx=\"3\" fill=\"rgba(255,255,255,0.25)\"/>\n            <rect x=\"640\" y=\"24\" width=\"80\" height=\"12\" rx=\"3\" fill=\"rgba(255,255,255,0.15)\"/>\n            <!-- Graphe vibrations -->\n            <rect x=\"20\" y=\"54\" width=\"470\" height=\"110\" rx=\"8\" fill=\"rgba(255,255,255,0.05)\" stroke=\"rgba(255,255,255,0.15)\" stroke-width=\"1\"/>\n            <rect x=\"36\" y=\"64\" width=\"80\" height=\"10\" rx=\"3\" fill=\"rgba(255,255,255,0.25)\"/>\n            <!-- Signal vibrations -->\n            <polyline points=\"36,148 80,130 100,142 130,118 160,138 190,110 220,128 250,112 280,130 310,108 340,125 370,105 400,122 430,110 460,128 480,138\" stroke=\"rgba(255,255,255,0.75)\" stroke-width=\"2\" fill=\"none\" stro